"""영역 경계 인터페이스 I1~I7의 Protocol(INTERFACES.md). 소유 영역이 구현하고, 소비 영역은 이것에 맞춰 개발한다.

레코드는 JSON을 그대로 옮긴 dict다. 필드와 형식은 schemas/*.schema.json이 정한다. 모든 메서드는 실패 시
boundary_contracts.errors.BoundaryError를 던진다. 같은 인터페이스를 지키는 메모리 구현은 소유 영역이 낸다.
"""
from __future__ import annotations

from datetime import datetime
from pathlib import Path
from typing import BinaryIO, Mapping, Optional, Protocol, runtime_checkable

Record = dict          # 경계 계약 레코드(JSON 객체)
Ref = dict             # ArtifactRef {id, version, content_hash}
Page = tuple           # (items: list, next_cursor: Optional[str])


@runtime_checkable
class QuestionReader(Protocol):
    """I1. 소유: question-authoring."""
    def get_question_bank(self, ref: Ref) -> dict: ...
    def latest(self, question_set_id: str, *, reviewed_only: bool = False) -> Ref: ...
    def list_versions(self, question_set_id: str, *, cursor: Optional[str] = None, limit: int = 100) -> Page: ...
    def get_reviews(self, ref: Ref) -> list[Record]: ...
    def get_change(self, ref: Ref) -> Optional[Record]: ...


@runtime_checkable
class DatasetStore(Protocol):
    """I2. 소유: synthetic-data."""
    def publish(self, manifest: Record, files: Mapping[str, Path]) -> Record: ...
    def get_manifest(self, dataset_id: str, version: str) -> Record: ...
    def list_versions(self, dataset_id: str) -> list[str]: ...
    def open_file(self, dataset_id: str, version: str, path: str) -> BinaryIO: ...


@runtime_checkable
class ModelRegistry(Protocol):
    """I3. 소유: model-lab."""
    def publish(self, manifest: Record, adapter_dir: Path, eval_report: bytes) -> Record: ...
    def get_manifest(self, package_id: str, version: str) -> Record: ...
    def list_versions(self, package_id: str) -> list[str]: ...
    def open_adapter(self, package_id: str, version: str, *, dest: Path) -> Path: ...
    def get_eval_report(self, ref: str) -> bytes: ...


@runtime_checkable
class ReleaseReader(Protocol):
    """I4. 소유: release-gate. load_bundle의 반환은 ReleaseBundle(manifest, question_bank, adapters)이다."""
    def get_active_pointer(self) -> Optional[Record]: ...
    def get_release(self, release_id: str) -> Record: ...
    def load_bundle(self, release_id: str, *, dest: Path) -> "ReleaseBundle": ...
    def get_decision(self, decision_id: str) -> Record: ...
    def find_decisions(self, *, question_set: Optional[Ref] = None, lora_a: Optional[Ref] = None,
                       lora_b: Optional[Ref] = None, submission_id: Optional[str] = None,
                       cursor: Optional[str] = None, limit: int = 100) -> Page: ...
    def list_releases(self, *, cursor: Optional[str] = None, limit: int = 100) -> Page: ...


class ReleaseBundle:
    """릴리스에 묶인 내용. adapters의 키는 'LORA_A'|'LORA_B'."""
    def __init__(self, manifest: Record, question_bank: dict, adapters: Mapping[str, Path]):
        self.manifest = manifest
        self.question_bank = question_bank
        self.adapters = dict(adapters)


@runtime_checkable
class GateService(Protocol):
    """I5. 소유: release-gate."""
    def submit_candidate(self, subject: Record, *, requested_by_role: str) -> Record: ...
    def activate(self, release_id: str, *, requested_by_role: str) -> Record: ...
    def request_rollback(self, request: Record) -> Record: ...


@runtime_checkable
class TraceIngest(Protocol):
    """I6. 소유: ops-feedback."""
    def send(self, envelope: Record) -> Record: ...


@runtime_checkable
class FailureStore(Protocol):
    """I7. 소유: ops-feedback."""
    def publish_case(self, case: Record) -> Record: ...
    def get_case(self, case_id: str, *, version: Optional[int] = None) -> Record: ...
    def list_cases(self, *, review_status: Optional[str] = None, failure_type: Optional[str] = None,
                   source_release_id: Optional[str] = None, updated_since: Optional[datetime] = None,
                   latest_only: bool = True, cursor: Optional[str] = None, limit: int = 100) -> Page: ...
    def get_trace(self, deidentified_trace_ref: str) -> dict: ...
